import{_ as t,o,c as a,ag as s}from"./chunks/framework.DNmTgtHf.js";const g=JSON.parse('{"title":"Lombok — Coding Exercises","description":"","frontmatter":{},"headers":[],"relativePath":"java/coding_fluency/lombok/Lombok.md","filePath":"java/coding_fluency/lombok/Lombok.md"}'),i={name:"java/coding_fluency/lombok/Lombok.md"};function n(r,e,d,c,l,u){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="lombok-—-coding-exercises" tabindex="-1">Lombok — Coding Exercises <a class="header-anchor" href="#lombok-—-coding-exercises" aria-label="Permalink to &quot;Lombok — Coding Exercises&quot;">​</a></h1><h2 id="why-this-matters" tabindex="-1">Why this matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why this matters&quot;">​</a></h2><p>Lombok eliminates the boilerplate around DTOs and service classes: constructors, getters, equals/hashCode, builders, and loggers. On a KYC platform these appear in every verification request, response DTO, and service component. Knowing exactly which methods each annotation generates — and where the gotchas are — is table stakes for code review at SDE2 level.</p><h2 id="domain-model" tabindex="-1">Domain model <a class="header-anchor" href="#domain-model" aria-label="Permalink to &quot;Domain model&quot;">​</a></h2><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// You will create Lombok-annotated versions of these two types in the exercises</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// (do not import Spring annotations unless explicitly asked)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// A verification result returned from the KYC engine</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> KycVerificationResult</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    String userId;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    String status;       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// e.g. &quot;APPROVED&quot;, &quot;REJECTED&quot;, &quot;PENDING&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    String reason;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    java.time.Instant verifiedAt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// A service that depends on two collaborators</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> KycVerificationService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    KycRepository repository;      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// final field</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    NotificationService notifier;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// final field</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="exercise-1-value-—-immutable-dto-10-min" tabindex="-1">Exercise 1: @Value — immutable DTO (~10 min) <a class="header-anchor" href="#exercise-1-value-—-immutable-dto-10-min" aria-label="Permalink to &quot;Exercise 1: @Value — immutable DTO (~10 min)&quot;">​</a></h2><p><strong>Goal:</strong> Use <code>@Value</code> to make <code>KycVerificationResult</code> fully immutable without writing accessors, constructors, or equals/hashCode by hand.</p><p><strong>What <code>@Value</code> generates:</strong> Shorthand for <code>@Getter</code> + <code>@FieldDefaults(level=PRIVATE, makeFinal=true)</code> + <code>@RequiredArgsConstructor</code> + <code>@EqualsAndHashCode</code> + <code>@ToString</code>. No setters.</p><p><strong>Task:</strong><br> Annotate <code>KycVerificationResult</code> with <code>@Value</code>. Then:</p><ol><li>Try to add a setter — what happens?</li><li>Try to set a field directly (<code>result.status = &quot;X&quot;</code>) — what happens?</li><li>Print the object — what does <code>toString()</code> look like without you writing it?</li><li>Create two instances with the same data and confirm <code>equals()</code> returns <code>true</code>.</li></ol><p><strong>Gotcha:</strong> <code>@Value</code> makes every field <code>private final</code> automatically — you do not write <code>final</code> yourself. Adding a non-final field manually compiles, but that field gets a setter generated, defeating immutability.</p><hr><h2 id="exercise-2-builder-value-—-build-then-lock-15-min" tabindex="-1">Exercise 2: @Builder + @Value — build-then-lock (~15 min) <a class="header-anchor" href="#exercise-2-builder-value-—-build-then-lock-15-min" aria-label="Permalink to &quot;Exercise 2: @Builder + @Value — build-then-lock (~15 min)&quot;">​</a></h2><p><strong>Goal:</strong> Combine <code>@Builder</code> with <code>@Value</code> to get a fluent builder producing immutable objects; use <code>toBuilder()</code> to derive modified copies.</p><p><strong>Task:</strong></p><ol><li>Add <code>@Builder</code> alongside <code>@Value</code> on <code>KycVerificationResult</code>. Build an instance using the generated builder.</li><li>Attempt to call a setter on the built object — confirm it doesn&#39;t exist.</li><li>Enable <code>toBuilder = true</code> on <code>@Builder</code>. Create a base result, then derive a new result with only <code>status</code> changed using <code>result.toBuilder().status(&quot;REJECTED&quot;).build()</code>. Confirm the original is unchanged.</li></ol><p><strong>Gotcha:</strong> <code>@Value</code> already synthesises an all-args constructor (via <code>@RequiredArgsConstructor</code> on all-final fields). <code>@Builder</code> alongside <code>@Value</code> works because Lombok coordinates the two, but adding a manual <code>@AllArgsConstructor</code> causes a &quot;duplicate constructor&quot; compile error — leave constructor generation to Lombok.<br><code>toBuilder()</code> is not generated unless you set <code>toBuilder = true</code> explicitly.</p><hr><h2 id="exercise-3-data-vs-value-—-mutation-boundary-10-min" tabindex="-1">Exercise 3: @Data vs @Value — mutation boundary (~10 min) <a class="header-anchor" href="#exercise-3-data-vs-value-—-mutation-boundary-10-min" aria-label="Permalink to &quot;Exercise 3: @Data vs @Value — mutation boundary (~10 min)&quot;">​</a></h2><p><strong>Goal:</strong> Understand exactly which methods each annotation generates and why <code>@Data</code> is unsuitable for immutable DTOs.</p><p><strong>Task:</strong><br> Create two versions of the same tiny class (e.g., <code>UserSummary</code> with <code>id</code> and <code>email</code>): one with <code>@Data</code>, one with <code>@Value</code>. For each, list:</p><table tabindex="0"><thead><tr><th>Method</th><th>@Data</th><th>@Value</th></tr></thead><tbody><tr><td>Getters</td><td></td><td></td></tr><tr><td>Setters</td><td></td><td></td></tr><tr><td>Constructor</td><td></td><td></td></tr><tr><td>equals/hashCode</td><td></td><td></td></tr><tr><td>toString</td><td></td><td></td></tr><tr><td>Field modifier</td><td></td><td></td></tr></tbody></table><p>Call a setter on the <code>@Data</code> version to confirm mutation is possible.</p><p><strong>Gotcha:</strong> <code>@Data</code> on a JPA entity is dangerous — Lombok&#39;s <code>equals</code>/<code>hashCode</code> includes all fields. If a lazy-loaded collection is touched during equals, Hibernate fires an extra query. Use <code>@EqualsAndHashCode(onlyExplicitlyIncluded = true)</code> on entities instead.</p><hr><h2 id="exercise-4-slf4j-—-structured-logging-10-min" tabindex="-1">Exercise 4: @Slf4j — structured logging (~10 min) <a class="header-anchor" href="#exercise-4-slf4j-—-structured-logging-10-min" aria-label="Permalink to &quot;Exercise 4: @Slf4j — structured logging (~10 min)&quot;">​</a></h2><p><strong>Goal:</strong> Wire up a logger without <code>Logger</code> declaration boilerplate; verify the logger name is the class name.</p><p><strong>Task:</strong><br> Add <code>@Slf4j</code> to <code>KycVerificationService</code>. Then write a <code>verify(String userId)</code> method that:</p><ol><li>Logs at <code>DEBUG</code> level: <code>&quot;Starting KYC verification for userId={}&quot;</code></li><li>Logs at <code>INFO</code> level: <code>&quot;Verification complete for userId={}, status={}&quot;</code></li><li>Logs at <code>ERROR</code> level with an exception: <code>&quot;Verification failed for userId={}&quot;</code> with a caught <code>RuntimeException</code>.</li></ol><p>Print <code>log.getClass().getName()</code> and <code>log.getName()</code> to confirm what Lombok wired.</p><p><strong>Gotcha:</strong> SLF4J&#39;s <code>{}</code> placeholder is not <code>String.format</code> — don&#39;t use <code>+</code> concatenation or <code>String.format()</code> in log calls. The placeholder defers string construction until the log level is enabled, which matters at high throughput.</p><hr><h2 id="exercise-5-requiredargsconstructor-—-constructor-injection-10-min" tabindex="-1">Exercise 5: @RequiredArgsConstructor — constructor injection (~10 min) <a class="header-anchor" href="#exercise-5-requiredargsconstructor-—-constructor-injection-10-min" aria-label="Permalink to &quot;Exercise 5: @RequiredArgsConstructor — constructor injection (~10 min)&quot;">​</a></h2><p><strong>Goal:</strong> Replace a hand-written constructor for final fields with <code>@RequiredArgsConstructor</code>; understand how Spring uses it.</p><p><strong>Task:</strong></p><ol><li>Write <code>KycVerificationService</code> manually with a constructor that takes <code>KycRepository</code> and <code>NotificationService</code> and assigns them to <code>final</code> fields.</li><li>Delete the constructor. Add <code>@RequiredArgsConstructor</code>. Confirm the class still compiles and the fields are assigned.</li><li>Add <code>@Component</code> (or <code>@Service</code>) to the class. Explain why Spring&#39;s constructor injection works here without <code>@Autowired</code> on the constructor (Spring 4.3+ injects automatically when there is exactly one constructor).</li></ol><p><strong>Gotcha:</strong> <code>@RequiredArgsConstructor</code> generates a constructor only for <code>final</code> fields and fields annotated <code>@NonNull</code>. A non-final field without <code>@NonNull</code> is silently excluded — forget <code>final</code> and the dependency is not injected and remains null at runtime.</p><hr><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q.</strong> What is the key difference between <code>@Data</code> and <code>@Value</code>?<br><strong>A.</strong> <code>@Data</code> generates setters and does not make fields final — objects are mutable. <code>@Value</code> makes all fields <code>private final</code> and generates no setters — objects are immutable.</p><p><strong>Q.</strong> Why does <code>@Builder</code> break Jackson deserialization by default?<br><strong>A.</strong> <code>@Builder</code> suppresses the no-arg constructor. Jackson needs a no-arg constructor (or an annotated builder) to deserialize JSON. The cleanest fix is <code>@Jacksonized</code> alongside <code>@Builder</code>; alternatively, add <code>@NoArgsConstructor</code> + <code>@AllArgsConstructor</code> and annotate the constructor with <code>@JsonCreator</code>.</p><p><strong>Q.</strong> What fields does <code>@RequiredArgsConstructor</code> include in the generated constructor?<br><strong>A.</strong> Only <code>final</code> fields and fields annotated <code>@NonNull</code>. Non-final, non-annotated fields are excluded.</p><p><strong>Q.</strong> Why is <code>@Data</code> dangerous on a JPA entity?<br><strong>A.</strong> Lombok&#39;s generated <code>equals</code>/<code>hashCode</code> includes all fields. Accessing a lazy-loaded collection during comparison triggers an extra Hibernate query and can cause <code>LazyInitializationException</code> outside a session.</p><p><strong>Q.</strong> What does <code>@Slf4j</code> actually inject?<br><strong>A.</strong> <code>private static final Logger log = LoggerFactory.getLogger(TheClass.class)</code> — the exact declaration Lombok writes at compile time. No runtime reflection; the logger name is always the fully-qualified class name.</p><p><strong>Q.</strong> How do you inspect what Lombok actually generated?<br><strong>A.</strong> Run <code>mvn lombok:delombok</code> — it writes the expanded source under <code>target/generated-sources/delombok/</code> so you can see exactly what was synthesised.</p>`,45)])])}const p=t(i,[["render",n]]);export{g as __pageData,p as default};
